// Typed Friday Hub client. src/schema.ts and openapi.json are generated by
// `pnpm gen`; never edit them by hand.
import createFetchClient from 'openapi-fetch'
import createQueryHooks from 'openapi-react-query'
import type { paths } from './schema.ts'

export type { components, operations, paths } from './schema.ts'

/** baseUrl '' = same origin (the web app, via the Vite proxy in dev). */
export function createApi(baseUrl = '', init: { token?: string } = {}) {
  const fetch = createFetchClient<paths>({
    baseUrl,
    credentials: 'include',
    headers: init.token ? { Authorization: `Bearer ${init.token}` } : undefined,
  })
  return { fetch, query: createQueryHooks(fetch) }
}
